USE dactest;
-- 创建资产负债核心表
CREATE TABLE balance_sheet (
    data_date DATE NOT NULL COMMENT '报表日期',
    branch_id VARCHAR(4) NOT NULL COMMENT '机构编号',
    branch_name VARCHAR(50) NOT NULL COMMENT '机构名称',
    
    -- 资产类
    total_assets DECIMAL(18,0) COMMENT '资产总额',
    customer_loans DECIMAL(18,0) COMMENT '客户贷款总额',
    interbank_assets DECIMAL(18,0) COMMENT '同业资产总额',
    other_assets DECIMAL(18,0) COMMENT '其他资产总额',
    
    -- 负债类
    total_liabilities DECIMAL(18,0) COMMENT '负债总额',
    customer_deposits DECIMAL(18,0) COMMENT '客户存款总额',
    interbank_liabilities DECIMAL(18,0) COMMENT '同业负债总额',
    other_liabilities DECIMAL(18,0) COMMENT '其他负债总额',
    
    -- 客户维度
    total_customers INT COMMENT '客户总数',
    individual_customers INT COMMENT '个人客户数',
    corporate_customers INT COMMENT '公司客户数',
    interbank_customers INT COMMENT '同业客户数',
    
    -- 人力资源
    total_employees INT COMMENT '员工总数',
    
    PRIMARY KEY (data_date, branch_id, branch_name)
) COMMENT='核心资产负债表';

