-- 创建数据表
CREATE TABLE deposit_data (
    data_date DATE COMMENT '数据日期（格式：YYYY/MM/DD）',
    branch_id VARCHAR(4) COMMENT '机构号（4位数字代码）',
    branch_name VARCHAR(50) COMMENT '机构名称',
    customer_deposit_total DECIMAL(18,0) COMMENT '客户存款总额（公司+零售，单位：元）',
    corporate_deposit_total DECIMAL(18,0) COMMENT '公司存款总额（单位：元）',
    corporate_current_deposit DECIMAL(18,0) COMMENT '公司活期存款（单位：元）',
    corporate_term_deposit DECIMAL(18,0) COMMENT '公司定期存款（单位：元）',
    retail_deposit_total DECIMAL(18,0) COMMENT '零售存款总额（单位：元）',
    retail_current_deposit DECIMAL(18,0) COMMENT '零售活期存款（单位：元）',
    retail_term_deposit DECIMAL(18,0) COMMENT '零售定期存款（单位：元）',
    PRIMARY KEY (data_date, branch_id, branch_name)
) COMMENT='存款总额';

-- 插入数据
-- 创建贷款数据表
CREATE TABLE loan_data (
    data_date DATE NOT NULL COMMENT '数据日期（格式：YYYY/MM/DD）',
    branch_id VARCHAR(4) NOT NULL COMMENT '机构号（4位数字代码）',
    branch_name VARCHAR(50) NOT NULL COMMENT '机构名称',
    total_customer_loan DECIMAL(18,0) COMMENT '客户贷款总额（单位：元）',
    substantive_loan_total DECIMAL(18,0) COMMENT '实质性贷款总额（实际发放的贷款，单位：元）',
    corporate_loan_total DECIMAL(18,0) COMMENT '公司贷款总额（单位：元）',
    inclusive_sme_loan DECIMAL(18,0) COMMENT '普惠小微贷款总额（单位：元）',
    retail_loan_total DECIMAL(18,0) COMMENT '零售贷款总额（单位：元）',
    credit_card_loan DECIMAL(18,0) COMMENT '信用卡贷款总额（单位：元）',
    medium_small_loan DECIMAL(18,0) COMMENT '中小额贷款总额（单位：元）',
    large_loan DECIMAL(18,0) COMMENT '大额贷款总额（单位：元）',
    medium_small_corporate_loan DECIMAL(18,0) COMMENT '中小额公司贷款（公司贷款子项，单位：元）',
    large_corporate_loan DECIMAL(18,0) COMMENT '大额公司贷款（公司贷款子项，单位：元）',
    total_discount DECIMAL(18,0) COMMENT '贴现总额（直贴+转贴，单位：元）',
    direct_discount DECIMAL(18,0) COMMENT '直贴总额（直接贴现业务，单位：元）',
    transfer_discount DECIMAL(18,0) COMMENT '转贴总额（转贴现业务，单位：元）',
    PRIMARY KEY (data_date, branch_id, branch_name)
) COMMENT='贷款数据表';

-- 导入贷款数据
-- 创建零售贷款明细表
CREATE TABLE retail_loan_detail (
    data_date DATE NOT NULL COMMENT '数据日期（格式：YYYY/MM/DD）',
    branch_id VARCHAR(4) NOT NULL COMMENT '机构号（4位数字代码）',
    branch_name VARCHAR(50) NOT NULL COMMENT '机构名称',
    retail_loan_total DECIMAL(18,2) COMMENT '零售贷款总额',
    mortgage_total DECIMAL(18,2) COMMENT '按揭贷款总额',
    first_hand_mortgage DECIMAL(18,2) COMMENT '一手按揭总额',
    second_hand_mortgage DECIMAL(18,2) COMMENT '二手按揭总额',
    consumer_loan_total DECIMAL(18,2) COMMENT '消费贷款总额',
    PRIMARY KEY (data_date, branch_id, branch_name)
) COMMENT='零售贷款明细表';

